// 可复现的规则题：ID 编码专项、模板、难度和种子，历史记录无需存储完整题目。
function generatedQuestion(id){if(!Number.isInteger(id)||id<1000000000)return null;let z=id-1000000000,cat=Math.floor(z/100000000),kind=Math.floor(z%100000000/10000000),level=Math.floor(z%10000000/1000000),seed=z%1000000;if(cat>2||kind>2||level<1||level>3)return null;let state=seed||1;function rnd(n){state=(Math.imul(state,1664525)+1013904223)>>>0;return state%n}let n=3+rnd(6),a=1+rnd(12),b=2+rnd(9),code,expected,explain,topic,steps=[],line=1,vars={},out='';const py=x=>Array.isArray(x)?'['+x.map(py).join(', ')+']':String(x),snap=(l,v,o='',event='line',scope='<module>',returned='None')=>steps.push({line:l,variables:Object.fromEntries(Object.entries(v).map(([k,x])=>[k,py(x)])),output:o,event,scope,returned});
if(cat===0){let list=Array.from({length:n},(_,i)=>a+i*b),result;
 if(kind===0){topic='切片';let start=1+rnd(n-1),end=start+1+rnd(n-start);let expr=level===1?`a[${start}]`:level===2?`a[${start}:${end}]`:'a[::-2]';result=level===1?list[start]:level===2?list.slice(start,end):list.slice().reverse().filter((_,i)=>i%2===0);code=`a = ${py(list)}\nprint(${expr})`;expected=py(result);explain=level===1?'索引从 0 开始，先定位元素。':level===2?'切片包含起点、不包含终点。':'负步长从右向左取值；步长 -2 每次向左移动两个位置。';snap(1,{});snap(2,{a:list});snap(2,{a:list},expected,'return');}
 if(kind===1){topic='添加元素';let extend=level===1?true:rnd(2)===0,extra=[a+b,a+2*b];list=[a];code=`a = [${a}]\na.${extend?'extend':'append'}(${py(extra)})\nprint(${level===3?'len(a)':'a'})`;snap(1,{});snap(2,{a:list});list=extend?list.concat(extra):list.concat([extra]);snap(3,{a:list});expected=level===3?String(list.length):py(list);snap(3,{a:list},expected,'return');explain='append 将参数整体作为一个元素加入；extend 逐个加入元素。len 只统计最外层元素。';}
 if(kind===2){topic='赋值与复制';let copy=rnd(2)===0,nested=level===3;list=nested?[[a],[b]]:[a,b];let orig=JSON.parse(JSON.stringify(list)),other=JSON.parse(JSON.stringify(list));code=`a = ${py(list)}\nb = a${copy?'.copy()':''}\nb[0]${nested?'[0]':''} = ${n}\nprint(a)`;snap(1,{});snap(2,{a:orig});snap(3,{a:orig,b:orig});if(nested){other[0][0]=n;list[0][0]=n}else{other[0]=n;if(!copy)list[0]=n}snap(4,{a:list,b:other});expected=py(list);snap(4,{a:list,b:other},expected,'return');explain=nested?'copy 是浅复制：外层列表不同，但内部列表仍共享，修改内层元素会影响原列表。':copy?'copy 创建新列表，替换副本的外层元素不会改变原列表。':'赋值没有复制列表，两个名称指向同一列表。';}
}else if(cat===1){let total=0;
 if(kind===0){topic='range 边界';let start=level===3?n:0,stop=level===3?0:n,delta=level===1?1:level===2?2:-2;code=`s = 0\nfor i in range(${start}, ${stop}, ${delta}):\n    s += i\nprint(s)`;snap(1,{});snap(2,{s:0});let last;for(let i=start;delta>0?i<stop:i>stop;i+=delta){last=i;snap(3,{s:total,i});total+=i;snap(2,{s:total,i})}snap(4,{s:total,i:last});expected=String(total);snap(4,{s:total,i:last},expected,'return');explain='range 包含起点、不包含终点；先按步长列出实际取值，再逐项累加。';}
 if(kind===1){topic='break 与 continue';let threshold=1+rnd(n-1),br=level===1||rnd(2)===0,condition=level===3?'i % 2 == 0':`i == ${threshold}`;code=`s = 0\nfor i in range(${n}):\n    if ${condition}:\n        ${br?'break':'continue'}\n    s += i\nprint(s)`;snap(1,{});snap(2,{s:0});let last;for(let i=0;i<n;i++){last=i;snap(3,{s:total,i});if(level===3?i%2===0:i===threshold){snap(4,{s:total,i});if(br)break;else{snap(2,{s:total,i});continue}}snap(5,{s:total,i});total+=i;snap(2,{s:total,i})}snap(6,{s:total,i:last});expected=String(total);snap(6,{s:total,i:last},expected,'return');explain=br?'条件满足时 break 终止整个循环，后续轮次都不会执行。':'条件满足时 continue 只跳过当前轮累加，后续轮次继续执行。';}
 if(kind===2){topic='累加初始化';let reset=level>1&&rnd(2)===0;code=`s = ${a}\nfor i in range(1, ${n}):\n${reset?`    s = ${a}\n`:''}    s += i\nprint(s)`;total=a;snap(1,{});snap(2,{s:total});for(let i=1;i<n;i++){if(reset){snap(3,{s:total,i});total=a}snap(reset?4:3,{s:total,i});total+=i;snap(2,{s:total,i})}snap(reset?5:4,{s:total,i:n-1});expected=String(total);snap(reset?5:4,{s:total,i:n-1},expected,'return');explain=reset?'循环内部重复初始化会丢掉之前的累积结果，只留下最后一轮。':'初始化在循环之前只执行一次，随后各轮在上一次结果上累加。';}
}else{
 if(kind===0){topic='打印与返回';let returns=level===1||rnd(2)===0,expr=level===3?'x * y':'x + y',value=level===3?a*b:a+b;code=`def f(x, y):\n    ${returns?'return ':'print('}${expr}${returns?'':')'}\nr = f(${a}, ${b})\nprint(r)`;snap(1,{});snap(3,{});snap(2,{x:a,y:b},'','line','f');snap(2,{x:a,y:b},returns?'':String(value),'return','f',returns?String(value):'None');snap(4,{r:returns?value:'None'},returns?'':String(value));expected=returns?String(value):value+'\nNone';snap(4,{r:returns?value:'None'},expected,'return');explain=returns?'return 把计算结果交给调用者，最后由外部 print 输出。':'内部 print 输出计算结果，但函数隐式返回 None，外部 print 还会输出 None。';}
 if(kind===1){topic='局部变量';code=`x = ${a}\ndef f(x):\n    x += ${b}\n    return x\ny = f(x)\nprint(${level===1?'x':level===2?'y':'x, y'})`;snap(1,{});snap(2,{x:a});snap(5,{x:a});snap(3,{x:a},'','line','f');snap(4,{x:a+b},'','line','f');snap(4,{x:a+b},'','return','f',String(a+b));snap(6,{x:a,y:a+b});expected=level===1?String(a):level===2?String(a+b):a+' '+(a+b);snap(6,{x:a,y:a+b},expected,'return');explain='函数内对整数形参重新赋值，只改变局部名称；返回值可由 y 接收，外部 x 保持原值。';}
 if(kind===2){topic='return 结束';let early=level>1&&rnd(2)===0;code=`def f():\n    s = ${a}\n    for i in range(1, ${n}):\n        s += i\n${early?'        ':'    '}return s\nprint(f())`;snap(1,{});snap(6,{});snap(2,{},'','line','f');let sum=a;snap(3,{s:sum},'','line','f');for(let i=1;i<n;i++){snap(4,{s:sum,i},'','line','f');sum+=i;if(early){snap(5,{s:sum,i},'','line','f');snap(5,{s:sum,i},'','return','f',String(sum));break}snap(3,{s:sum,i},'','line','f')}if(!early){snap(5,{s:sum,i:n-1},'','line','f');snap(5,{s:sum,i:n-1},'','return','f',String(sum))}expected=String(sum);snap(6,{},expected,'return');explain=early?'return 缩进在循环内部，第一轮累加后整个函数就结束。':'return 在循环外部，所有轮次累加完成后才返回。';}
}
let wrong;if(/^-?\d+$/.test(expected)){let v=Number(expected);wrong=[String(v+1),String(v-1)]}else if(expected.startsWith('[')){let v=JSON.parse(expected);wrong=[py(v.slice().reverse()),py(v.slice(0,-1))];if(wrong[0]===expected)wrong[0]=py(v.concat([0]));if(wrong[1]===wrong[0]||wrong[1]===expected)wrong[1]='None'}else if(expected.includes('\n')){wrong=[expected.split('\n')[0],expected.split('\n').reverse().join('\n')]}else{wrong=[expected.split(' ')[0],'None']}let options=[expected,...wrong];let shift=rnd(3);options=options.slice(shift).concat(options.slice(0,shift));return {id,category:cats[cat],topic,code,display:code,kind:'个性化新题 · 输出选择',prompt:'这段代码会输出什么？先独立推演，再查看过程。',answer:expected,expected,options,explain,steps,level:['','基础','进阶','挑战'][level],generated:true}}
function learnerLevel(category){let r=records(category).slice(-10);if(r.length<5)return 1;let score=r.reduce((s,x)=>s+(x.ok?(x.hint===0?1:x.hint<3?.5:0):0),0)/r.length;return score>=.85?3:score>=.6?2:1}
function adaptiveStart(){let chosen=[],reason=[],plan=db.plan?.focus;let counts=cats.map(c=>({c,rs:records(c).slice(-10)}));counts.sort((a,b)=>{let score=x=>x.rs.length?x.rs.reduce((s,r)=>s+(r.ok&&!r.hint?1:0),0)/x.rs.length:-1;return score(a)-score(b)});let focus=plan&&plan!=='均衡学习'?plan:counts[0].c;let used=new Set(db.records.map(r=>r.id));let recent=records(focus).slice(-10),weak=recent.filter(r=>!r.ok||r.hint>0).map(r=>getq(r.id).topic);const topics=[['切片','添加元素','赋值与复制'],['range 边界','break 与 continue','累加初始化'],['打印与返回','局部变量','return 结束']];for(let i=0;i<5;i++){let c=i<3?focus:cats[(cats.indexOf(focus)+i-2)%3],ci=cats.indexOf(c),level=learnerLevel(c),kind=i<3&&weak.length?topics[ci].indexOf(weak[weak.length-1]):i%3;if(kind<0)kind=i%3;let id;do{id=1000000000+ci*100000000+kind*10000000+level*1000000+Math.floor(Math.random()*999999)+1}while(used.has(id));used.add(id);chosen.push(id)}db.adaptiveReason=`本组 3 题聚焦${focus}，另 2 题拓展其他专项。${recent.length?'依据近期独立答对与提示记录调整难度。':'目前记录较少，先从基础题建立学习起点。'}新题由规则模板生成，未使用 AI 判分。`;start(null,chosen)}
const previousRender=render;render=function(){previousRender();if(['home','stats','plan'].includes(page)){document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card" style="margin-top:24px"><div class="row"><div><span class="eyebrow">ADAPTIVE PRACTICE</span><h3>下一组，为你而出。</h3><p>根据你的近期表现调整知识点与难度，每次生成 5 道新变式。<br>题库无限 · 每轮按学习记录生成 · 错题仍可原样重做</p></div>${btn('生成我的下一组 →','adaptiveStart()','primary')}</div></section>`)}if(page==='practice'&&db.session?.ids.some(id=>id>=1000000000)){document.querySelector('#app').insertAdjacentHTML('afterbegin',`<div class="notice">${esc(db.adaptiveReason||'这是根据学习记录生成的巩固练习。')}<br>${btn('再生成一组新题','adaptiveStart()')}</div>`)}};render();
